mapper.select:


    u.status = #{status}
    AND u.dept_id = #{deptId}

        AND (u.use_no LIKE CONCAT('%', #{keyword}, '%') OR u.remark LIKE CONCAT('%', #{keyword}, '%')
             OR EXISTS (SELECT 1 FROM fin_consumable_use_item i JOIN wms_material m ON m.id = i.material_id
                        WHERE i.use_id = u.id AND (m.code LIKE CONCAT('%', #{keyword}, '%') OR m.name LIKE CONCAT('%', #{keyword}, '%'))))


ORDER BY u.id DESC
